INSERT INTO ui.dashboardquery (
idashboardqueryid, bparametersrequired, vcdashboardquery, formattingrequiered, runonanalytics, transposerequired, imenustructuredesc, itenantid) VALUES (
'155'::integer, false::boolean, 'with d1 as (select mappingid from ui.webusermapping where webuserid = :loggedinuser and mappingtype = ''Workflow'')
(select workflowname as "label", workflowkey as "value" FROM ui.workflowmasters where
(workflowid in (select mappingid from d1) or -1 
in (select mappingid from d1)) and itenantid=:tenantid
and is_filter_display=true) ORDER BY label
'::text, false::boolean, false::boolean, false::boolean, '582'::integer, '12'::integer)
 returning idashboardqueryid,itenantid;


INSERT INTO ui.dashboardquery (
idashboardqueryid, bparametersrequired, vcfilterparametersjson, vcdashboardquery, formattingrequiered, runonanalytics, transposerequired, imenustructuredesc, itenantid) VALUES (
'156'::integer, false::boolean, null , 'SELECT X.* 
FROM (
