 UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{ 
  "NPCI":"SELECT X.* FROM (VALUES (''All'', ''All''), (''Assumed Genuine'', ''Assumed-Genuine''), (''Confirmed Genuine'', ''Confirmed-Genuine''), (''Undetermined'', ''Undetermined''), (''SIMSWAP'', ''SIMSWAP''), (''FAKCOL'', ''FAKCOL''), (''NEWMO'', ''NEWMO''), (''SMSSP'', ''SMSSP''), (''RACC'', ''RACC''), (''FSMS'', ''FSMS''), (''QRGALRY'', ''QRGALRY''), (''QRCAM'', ''QRCAM''), (''FAKEINV'', ''FAKEINV''), (''FAKELON'', ''FAKELON''), (''DURESS'', ''DURESS''), (''FAKLTRY'', ''FAKLTRY''), (''SELFINT'', ''SELFINT'')) AS X (\\"label\\", \\"value\\")",
  "CPFIR":"SELECT X.* FROM (VALUES (''All'', ''All''), (''ACH'', ''AccountHacking''), (''PHH'', ''Phishing''), (''RMD'', ''RemoteCapture''), (''LSI'', ''LostDevice''), (''CRS'', ''CardSkimming''), (''VIS'', ''Vishing''), (''SMI'', ''Smishing''), (''SIS'', ''SIMSwap''), (''WBC'', ''WebsiteCloning''), (''FRA'', ''FraudulentApp''), (''EHC'', ''EmailCompromise''), (''FMP'', ''Forgery''), (''MRC'', ''MerchantCollusion''), (''CLR'', ''CollectPaymentRequest''), (''OTH'', ''Oth'')) AS X (\\"label\\", \\"value\\")"
}'::text WHERE
idashboardqueryid = 157 AND itenantid = 12;


UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{ 
  "NPCI":
  {
    "All":  "SELECT payerphone.text_ AS \\"Payer Mobile No\\", CONCAT(cast(convert_from(Txnorg.bytes_, ''UTF8'') AS jsonb)->''payer''->''attribs''->''account_detail''->>''accountNumber'', cast(convert_from(Txnorg.bytes_, ''UTF8'') AS jsonb)->''payer''->''attribs''->''account_detail''->>''ifsc'') AS \\"Payer VPA\\", ''9767001'' AS \\"Remitter MMID\\", ''9730314999'' AS \\"Remitter Mobile No\\", TO_CHAR(date(hiproinst.start_time_), ''DDMMYYYY'') AS \\"Date\\",  CAST(hiproinst.start_time_ AS TIME) AS \\"Time\\", cast(convert_from(Txnorg.bytes_, ''UTF8'') AS jsonb)->''txn''->''attribs''->>''referenceNumber'' AS \\"RRN\\", TransactionAmount.double_ /100 AS \\"Amount\\", TransactionClass.text_ AS \\"Product\\", Fraudtype.text_ AS \\"Fraud Type\\" FROM camunda.act_hi_procinst hiproinst LEFT JOIN camunda.act_hi_varinst payerphone ON payerphone.proc_inst_id_ = hiproinst.proc_inst_id_ AND payerphone.name_ = ''payerphone'' LEFT JOIN camunda.act_hi_varinst TransactionAmount ON TransactionAmount.proc_inst_id_ = hiproinst.proc_inst_id_ AND TransactionAmount.name_ = ''TransactionAmount'' LEFT JOIN camunda.act_hi_varinst TransactionClass ON TransactionClass.proc_inst_id_ = hiproinst.proc_inst_id_ AND TransactionClass.name_ = ''TransactionClass'' LEFT JOIN camunda.act_hi_varinst Fraudtype ON Fraudtype.proc_inst_id_ = hiproinst.proc_inst_id_ AND Fraudtype.name_ = ''regulatoryReportingComment'' LEFT JOIN camunda.act_hi_varinst Txn ON Txn.proc_inst_id_ = hiproinst.proc_inst_id_ AND Txn.name_ = ''Transaction'' LEFT JOIN camunda.act_ge_bytearray Txnorg ON Txnorg.id_ = Txn.bytearray_id_   LEFT JOIN camunda.act_hi_varinst isfraud ON isfraud.proc_inst_id_ = hiproinst.proc_inst_id_ AND isfraud.name_ = ''Action''  WHERE date(hiproinst.start_time_) = :Date AND hiproinst.tenant_id_ = :tenantidstr and hiproinst.proc_def_key_ = :CaseType and TransactionClass.text_ in (''UPI'', ''IMPS'') and isfraud.text_= ''Value_Fraud'' limit 10000; ",
    "Other":"SELECT payerphone.text_ AS \\"Payer Mobile No\\", CONCAT(cast(convert_from(Txnorg.bytes_, ''UTF8'') AS jsonb)->''payer''->''attribs''->''account_detail''->>''accountNumber'', cast(convert_from(Txnorg.bytes_, ''UTF8'') AS jsonb)->''payer''->''attribs''->''account_detail''->>''ifsc'') AS \\"Payer VPA\\", ''9767001'' AS \\"Remitter MMID\\", ''9730314999'' AS \\"Remitter Mobile No\\", TO_CHAR(date(hiproinst.start_time_), ''DDMMYYYY'') AS \\"Date\\",  CAST(hiproinst.start_time_ AS TIME) AS \\"Time\\", cast(convert_from(Txnorg.bytes_, ''UTF8'') AS jsonb)->''txn''->''attribs''->>''referenceNumber'' AS \\"RRN\\", TransactionAmount.double_ /100 AS \\"Amount\\", TransactionClass.text_ AS \\"Product\\", Fraudtype.text_ AS \\"Fraud Type\\" FROM camunda.act_hi_procinst hiproinst LEFT JOIN camunda.act_hi_varinst payerphone ON payerphone.proc_inst_id_ = hiproinst.proc_inst_id_ AND payerphone.name_ = ''payerphone'' LEFT JOIN camunda.act_hi_varinst TransactionAmount ON TransactionAmount.proc_inst_id_ = hiproinst.proc_inst_id_ AND TransactionAmount.name_ = ''TransactionAmount'' LEFT JOIN camunda.act_hi_varinst TransactionClass ON TransactionClass.proc_inst_id_ = hiproinst.proc_inst_id_ AND TransactionClass.name_ = ''TransactionClass'' LEFT JOIN camunda.act_hi_varinst Fraudtype ON Fraudtype.proc_inst_id_ = hiproinst.proc_inst_id_ AND Fraudtype.name_ = ''regulatoryReportingComment'' LEFT JOIN camunda.act_hi_varinst Txn ON Txn.proc_inst_id_ = hiproinst.proc_inst_id_ AND Txn.name_ = ''Transaction'' LEFT JOIN camunda.act_ge_bytearray Txnorg ON Txnorg.id_ = Txn.bytearray_id_   LEFT JOIN camunda.act_hi_varinst isfraud ON isfraud.proc_inst_id_ = hiproinst.proc_inst_id_ AND isfraud.name_ = ''Action''  WHERE date(hiproinst.start_time_) = :Date AND hiproinst.tenant_id_ = :tenantidstr and hiproinst.proc_def_key_ = :CaseType and TransactionClass.text_ in (''UPI'', ''IMPS'') and isfraud.text_= ''Value_Fraud'' AND Fraudtype.text_ = :FraudCategory limit 10000;"
  },
  "CPFIR":
  {
    "All":  " WITH FraudNatureMapping AS ( SELECT ''All'' AS full_form, ''All'' AS short_form UNION ALL SELECT ''AccountHacking'', ''ACH'' UNION ALL SELECT ''Phishing'', ''PHH'' UNION ALL SELECT ''RemoteCapture'', ''RMD'' UNION ALL SELECT ''LostDevice'', ''LSI'' UNION ALL SELECT ''CardSkimming'', ''CRS'' UNION ALL SELECT ''Vishing'', ''VIS'' UNION ALL SELECT ''Smishing'', ''SMI'' UNION ALL SELECT ''SIMSwap'', ''SIS'' UNION ALL SELECT ''WebsiteCloning'', ''WBC'' UNION ALL SELECT ''FraudulentApp'', ''FRA'' UNION ALL SELECT ''EmailCompromise'', ''EHC'' UNION ALL SELECT ''Forgery'', ''FMP'' UNION ALL SELECT ''MerchantCollusion'', ''MRC'' UNION ALL SELECT ''CollectPaymentRequest'', ''CLR'' UNION ALL SELECT ''Other'', ''OTH'' ) SELECT internalIdentifier.text_ AS \\"Internal Identifier used by bank/ non-bank entity\\", ''Y'' AS \\"Was the Fraud Reported by Customer?\\", ''N'' AS \\"Was it an Attempted Fraud?\\", ''BNK'' AS \\"Payment Transaction Instrument used\\", CASE WHEN txn_class.text_ IN (''UPI'', ''IMPS'', ''AEPS'') THEN ''NOP'' WHEN txn_class.text_ IN (''NEFT'', ''RTGS'') THEN ''ROB'' ELSE NULL END AS \\"Payment System Category\\", TransactionClass.text_ AS \\"System Involved in the fraudulent transaction\\", cast(convert_from(Txnorg.bytes_, ''UTF8'') AS jsonb)->''txn''->''attribs''->''device''->>''type'' AS \\"Payment Channel Used for fraudulent transaction\\", FraudNatureMapping.short_form AS \\"Nature of Fraudulent transaction\\", TO_CHAR(transaction_timestamp.text_::TIMESTAMP, ''DDMMYYYY'') AS \\"Date of occurrence of fraud transaction reported by customer\\", SUBSTRING(transaction_timestamp.text_ FROM 12 FOR 8) AS \\"Time of occurrence of fraud transaction reported by customer\\", TO_CHAR(TO_TIMESTAMP(reportingDate.long_ / 1000), ''DDMMYYYY'')  AS \\"Reporting date of fraud by customer to bank /PPI Issuer /PSO\\", TO_CHAR(hiproinst.start_time_, ''DDMMYYYY'') AS \\"Date of entering the fraud by bank/PPI Issuer/PSO in the system\\", cast(convert_from(Txnorg.bytes_, ''UTF8'') AS jsonb)->''txn''->''attribs''->>''referenceNumber'' AS \\"Unique Transaction Reference No. of the Fraudulent transaction\\", ''Y'' AS \\"Is the fraud a Domestic Transaction?\\", payername.text_ AS \\"Reporting Customer Name\\", payerphone.text_ AS \\"Reporting Customer Mobile No.\\", payeremail.text_ AS \\"Reporting Customer Email\\", null AS \\"Any Other detail of the Reporting Customer\\", CASE WHEN cast(convert_from(Txnorg.bytes_, ''UTF8'') AS jsonb)->''txn''->''attribs''->''device''->>''app'' ILIKE ''%JIO%'' THEN ''N'' ELSE ''Y'' END AS \\"Was any Third party PSP involved?\\", CASE WHEN cast(convert_from(Txnorg.bytes_, ''UTF8'') AS jsonb)->''txn''->''attribs''->''device''->>''app'' ILIKE ''%JIO%'' THEN NULL ELSE cast(convert_from(Txnorg.bytes_, ''UTF8'') AS jsonb)->''txn''->''attribs''->''device''->>''app'' END AS \\"If Third party PSP involved, the name may be provided\\", TransactionAmount.double_ /100 AS \\"Amount involved (INR actuals) in the Fraudulent Transaction\\", null AS \\"Amount Recovered (INR actuals) in the Fraudulent Transaction\\", null AS \\"Was Insurance Coverage available?\\", null AS \\"Name of Insurer and per transaction coverage amount\\", null AS \\"Amount recovered due to Insurance cover\\", null AS \\"Beneficiary Name\\", null AS \\"Beneficiary Mobile\\", null AS \\"Beneficiary Email\\", cast(convert_from(Txnorg.bytes_, ''UTF8'') AS jsonb)->''payee''->''attribs''->''account_detail''->>''accountNumber'' AS \\"Beneficiary Account Number\\", null AS \\"Beneficiary Bank\\", null AS \\"Beneficiary branch(Part1 Code)\\", cast(convert_from(Txnorg.bytes_, ''UTF8'') AS jsonb)->''payee''->''attribs''->''account_detail''->>''bankIfsc'' AS \\"Beneficiary branch IFSC\\", NULL AS \\"Beneficiary PAN Card No.\\", NULL AS \\"Beneficiary Debit/Credit Card No.\\", NULL AS \\"Beneficiary PPI Card / Wallet No.\\", NULL AS \\"Beneficiary UPI ID\\", NULL AS \\"Name of Destination PPI Issuer\\", NULL AS \\"Destination Merchant ID\\", NULL AS \\"Destination Merchant Name\\", NULL AS \\"Destination Payment Gateway / Aggregator\\", NULL AS \\"Destination ATM ID\\", NULL AS \\"Suspect Website used\\", NULL AS \\"Suspect Mobile App used\\", NULL AS \\"Suspect Device ID\\", NULL AS \\"Suspect IP Address\\", NULL AS \\"Suspect IMEI Number\\", NULL AS \\"Suspect GeoTag ID\\", NULL AS \\"Any Other details of Suspect\\", NULL AS \\"Initial Inputs on Modus operandi of Fraud\\", NULL AS \\"Modus operandi -Update 1\\", NULL AS \\"Modus operandi -Update 2\\", NULL AS \\"Modus operandi -Update 3\\", NULL AS \\"Modus operandi -Update 4\\", NULL AS \\"Modus operandi -Update 5\\", NULL AS \\"False Alert - Transaction was Not a Fraud (Y/N)\\", NULL AS \\"Fraud Registered with Law Enforcement Agencies(LEA)/Sub-judice\\", NULL AS \\"If fraud was registered with LEA, details of case reported\\", ''Y'' AS \\"Has the Fraud incident been Closed?\\", TO_CHAR(hiproinst.start_time_, ''DDMMYYYY'') AS \\"Date of Closure of fraud\\", Remarks.text_ AS \\"Justification for closure of fraud\\", NULL AS \\"Any other Information pertaining to the fraud\\", NULL AS \\"Steps taken to address/prevent such frauds in future\\" FROM camunda.act_hi_procinst hiproinst LEFT JOIN camunda.act_hi_varinst internalIdentifier ON internalIdentifier.proc_inst_id_ = hiproinst.proc_inst_id_ AND internalIdentifier.name_ = ''internalIdentifier'' LEFT JOIN camunda.act_hi_varinst txn_class ON txn_class.proc_inst_id_ = hiproinst.proc_inst_id_ AND txn_class.name_ = ''txn_class'' LEFT JOIN camunda.act_hi_varinst TransactionClass ON TransactionClass.proc_inst_id_ = hiproinst.proc_inst_id_ AND TransactionClass.name_ = ''TransactionClass'' LEFT JOIN camunda.act_hi_varinst transaction_timestamp ON transaction_timestamp.proc_inst_id_ = hiproinst.proc_inst_id_ AND transaction_timestamp.name_ = ''transaction_timestamp'' LEFT JOIN camunda.act_hi_varinst reportingDate ON reportingDate.proc_inst_id_ = hiproinst.proc_inst_id_ AND reportingDate.name_ = ''reportingDate'' LEFT JOIN camunda.act_hi_varinst NatureOfFraud ON NatureOfFraud.proc_inst_id_ = hiproinst.proc_inst_id_ AND NatureOfFraud.name_ = ''Action2'' LEFT JOIN FraudNatureMapping ON NatureOfFraud.text_ = FraudNatureMapping.full_form LEFT JOIN camunda.act_hi_varinst TransactionAmount ON TransactionAmount.proc_inst_id_ = hiproinst.proc_inst_id_ AND TransactionAmount.name_ = ''TransactionAmount'' LEFT JOIN camunda.act_hi_varinst payername ON payername.proc_inst_id_ = hiproinst.proc_inst_id_ AND payername.name_ = ''payername'' LEFT JOIN camunda.act_hi_varinst payerphone ON payerphone.proc_inst_id_ = hiproinst.proc_inst_id_ AND payerphone.name_ = ''payerphone'' LEFT JOIN camunda.act_hi_varinst payeremail ON payeremail.proc_inst_id_ = hiproinst.proc_inst_id_ AND payeremail.name_ = ''payeremail'' LEFT JOIN camunda.act_hi_varinst Remarks ON Remarks.proc_inst_id_ = hiproinst.proc_inst_id_ AND Remarks.name_ = ''Remarks'' LEFT JOIN camunda.act_hi_varinst Txn ON Txn.proc_inst_id_ = hiproinst.proc_inst_id_ AND Txn.name_ = ''Transaction'' LEFT JOIN camunda.act_ge_bytearray Txnorg ON Txnorg.id_ = Txn.bytearray_id_ LEFT JOIN camunda.act_hi_varinst isfraud ON isfraud.proc_inst_id_ = hiproinst.proc_inst_id_ AND isfraud.name_ = ''Action'' WHERE DATE(hiproinst.start_time_) = :Date AND hiproinst.proc_def_key_ = :CaseType AND hiproinst.tenant_id_ = :tenantidstr and isfraud.text_= ''Value_Fraud'' limit 10000;",
    "Other":" WITH FraudNatureMapping AS ( SELECT ''All'' AS full_form, ''All'' AS short_form UNION ALL SELECT ''AccountHacking'', ''ACH'' UNION ALL SELECT ''Phishing'', ''PHH'' UNION ALL SELECT ''RemoteCapture'', ''RMD'' UNION ALL SELECT ''LostDevice'', ''LSI'' UNION ALL SELECT ''CardSkimming'', ''CRS'' UNION ALL SELECT ''Vishing'', ''VIS'' UNION ALL SELECT ''Smishing'', ''SMI'' UNION ALL SELECT ''SIMSwap'', ''SIS'' UNION ALL SELECT ''WebsiteCloning'', ''WBC'' UNION ALL SELECT ''FraudulentApp'', ''FRA'' UNION ALL SELECT ''EmailCompromise'', ''EHC'' UNION ALL SELECT ''Forgery'', ''FMP'' UNION ALL SELECT ''MerchantCollusion'', ''MRC'' UNION ALL SELECT ''CollectPaymentRequest'', ''CLR'' UNION ALL SELECT ''Other'', ''OTH'' ) SELECT internalIdentifier.text_ AS \\"Internal Identifier used by bank/ non-bank entity\\", ''Y'' AS \\"Was the Fraud Reported by Customer?\\", ''N'' AS \\"Was it an Attempted Fraud?\\", ''BNK'' AS \\"Payment Transaction Instrument used\\", CASE WHEN txn_class.text_ IN (''UPI'', ''IMPS'', ''AEPS'') THEN ''NOP'' WHEN txn_class.text_ IN (''NEFT'', ''RTGS'') THEN ''ROB'' ELSE NULL END AS \\"Payment System Category\\", TransactionClass.text_ AS \\"System Involved in the fraudulent transaction\\", cast(convert_from(Txnorg.bytes_, ''UTF8'') AS jsonb)->''txn''->''attribs''->''device''->>''type'' AS \\"Payment Channel Used for fraudulent transaction\\", FraudNatureMapping.short_form AS \\"Nature of Fraudulent transaction\\", TO_CHAR(transaction_timestamp.text_::TIMESTAMP, ''DDMMYYYY'') AS \\"Date of occurrence of fraud transaction reported by customer\\", SUBSTRING(transaction_timestamp.text_ FROM 12 FOR 8) AS \\"Time of occurrence of fraud transaction reported by customer\\", TO_CHAR(TO_TIMESTAMP(reportingDate.long_ / 1000), ''DDMMYYYY'')  AS \\"Reporting date of fraud by customer to bank /PPI Issuer /PSO\\", TO_CHAR(hiproinst.start_time_, ''DDMMYYYY'') AS \\"Date of entering the fraud by bank/PPI Issuer/PSO in the system\\", cast(convert_from(Txnorg.bytes_, ''UTF8'') AS jsonb)->''txn''->''attribs''->>''referenceNumber'' AS \\"Unique Transaction Reference No. of the Fraudulent transaction\\", ''Y'' AS \\"Is the fraud a Domestic Transaction?\\", payername.text_ AS \\"Reporting Customer Name\\", payerphone.text_ AS \\"Reporting Customer Mobile No.\\", payeremail.text_ AS \\"Reporting Customer Email\\", null AS \\"Any Other detail of the Reporting Customer\\", CASE WHEN cast(convert_from(Txnorg.bytes_, ''UTF8'') AS jsonb)->''txn''->''attribs''->''device''->>''app'' ILIKE ''%JIO%'' THEN ''N'' ELSE ''Y'' END AS \\"Was any Third party PSP involved?\\", CASE WHEN cast(convert_from(Txnorg.bytes_, ''UTF8'') AS jsonb)->''txn''->''attribs''->''device''->>''app'' ILIKE ''%JIO%'' THEN NULL ELSE cast(convert_from(Txnorg.bytes_, ''UTF8'') AS jsonb)->''txn''->''attribs''->''device''->>''app'' END AS \\"If Third party PSP involved, the name may be provided\\", TransactionAmount.double_ /100 AS \\"Amount involved (INR actuals) in the Fraudulent Transaction\\", null AS \\"Amount Recovered (INR actuals) in the Fraudulent Transaction\\", null AS \\"Was Insurance Coverage available?\\", null AS \\"Name of Insurer and per transaction coverage amount\\", null AS \\"Amount recovered due to Insurance cover\\", null AS \\"Beneficiary Name\\", null AS \\"Beneficiary Mobile\\", null AS \\"Beneficiary Email\\", cast(convert_from(Txnorg.bytes_, ''UTF8'') AS jsonb)->''payee''->''attribs''->''account_detail''->>''accountNumber'' AS \\"Beneficiary Account Number\\", null AS \\"Beneficiary Bank\\", null AS \\"Beneficiary branch(Part1 Code)\\", cast(convert_from(Txnorg.bytes_, ''UTF8'') AS jsonb)->''payee''->''attribs''->''account_detail''->>''bankIfsc'' AS \\"Beneficiary branch IFSC\\", NULL AS \\"Beneficiary PAN Card No.\\", NULL AS \\"Beneficiary Debit/Credit Card No.\\", NULL AS \\"Beneficiary PPI Card / Wallet No.\\", NULL AS \\"Beneficiary UPI ID\\", NULL AS \\"Name of Destination PPI Issuer\\", NULL AS \\"Destination Merchant ID\\", NULL AS \\"Destination Merchant Name\\", NULL AS \\"Destination Payment Gateway / Aggregator\\", NULL AS \\"Destination ATM ID\\", NULL AS \\"Suspect Website used\\", NULL AS \\"Suspect Mobile App used\\", NULL AS \\"Suspect Device ID\\", NULL AS \\"Suspect IP Address\\", NULL AS \\"Suspect IMEI Number\\", NULL AS \\"Suspect GeoTag ID\\", NULL AS \\"Any Other details of Suspect\\", NULL AS \\"Initial Inputs on Modus operandi of Fraud\\", NULL AS \\"Modus operandi -Update 1\\", NULL AS \\"Modus operandi -Update 2\\", NULL AS \\"Modus operandi -Update 3\\", NULL AS \\"Modus operandi -Update 4\\", NULL AS \\"Modus operandi -Update 5\\", NULL AS \\"False Alert - Transaction was Not a Fraud (Y/N)\\", NULL AS \\"Fraud Registered with Law Enforcement Agencies(LEA)/Sub-judice\\", NULL AS \\"If fraud was registered with LEA, details of case reported\\", ''Y'' AS \\"Has the Fraud incident been Closed?\\", TO_CHAR(hiproinst.start_time_, ''DDMMYYYY'') AS \\"Date of Closure of fraud\\", Remarks.text_ AS \\"Justification for closure of fraud\\", NULL AS \\"Any other Information pertaining to the fraud\\", NULL AS \\"Steps taken to address/prevent such frauds in future\\" FROM camunda.act_hi_procinst hiproinst LEFT JOIN camunda.act_hi_varinst internalIdentifier ON internalIdentifier.proc_inst_id_ = hiproinst.proc_inst_id_ AND internalIdentifier.name_ = ''internalIdentifier'' LEFT JOIN camunda.act_hi_varinst txn_class ON txn_class.proc_inst_id_ = hiproinst.proc_inst_id_ AND txn_class.name_ = ''txn_class'' LEFT JOIN camunda.act_hi_varinst TransactionClass ON TransactionClass.proc_inst_id_ = hiproinst.proc_inst_id_ AND TransactionClass.name_ = ''TransactionClass'' LEFT JOIN camunda.act_hi_varinst transaction_timestamp ON transaction_timestamp.proc_inst_id_ = hiproinst.proc_inst_id_ AND transaction_timestamp.name_ = ''transaction_timestamp'' LEFT JOIN camunda.act_hi_varinst reportingDate ON reportingDate.proc_inst_id_ = hiproinst.proc_inst_id_ AND reportingDate.name_ = ''reportingDate'' LEFT JOIN camunda.act_hi_varinst NatureOfFraud ON NatureOfFraud.proc_inst_id_ = hiproinst.proc_inst_id_ AND NatureOfFraud.name_ = ''Action2'' LEFT JOIN FraudNatureMapping ON NatureOfFraud.text_ = FraudNatureMapping.full_form LEFT JOIN camunda.act_hi_varinst TransactionAmount ON TransactionAmount.proc_inst_id_ = hiproinst.proc_inst_id_ AND TransactionAmount.name_ = ''TransactionAmount'' LEFT JOIN camunda.act_hi_varinst payername ON payername.proc_inst_id_ = hiproinst.proc_inst_id_ AND payername.name_ = ''payername'' LEFT JOIN camunda.act_hi_varinst payerphone ON payerphone.proc_inst_id_ = hiproinst.proc_inst_id_ AND payerphone.name_ = ''payerphone'' LEFT JOIN camunda.act_hi_varinst payeremail ON payeremail.proc_inst_id_ = hiproinst.proc_inst_id_ AND payeremail.name_ = ''payeremail'' LEFT JOIN camunda.act_hi_varinst Remarks ON Remarks.proc_inst_id_ = hiproinst.proc_inst_id_ AND Remarks.name_ = ''Remarks'' LEFT JOIN camunda.act_hi_varinst Txn ON Txn.proc_inst_id_ = hiproinst.proc_inst_id_ AND Txn.name_ = ''Transaction'' LEFT JOIN camunda.act_ge_bytearray Txnorg ON Txnorg.id_ = Txn.bytearray_id_ LEFT JOIN camunda.act_hi_varinst isfraud ON isfraud.proc_inst_id_ = hiproinst.proc_inst_id_ AND isfraud.name_ = ''Action'' WHERE DATE(hiproinst.start_time_) = :Date AND hiproinst.proc_def_key_ = :CaseType AND hiproinst.tenant_id_ = :tenantidstr and isfraud.text_= ''Value_Fraud'' AND NatureOfFraud.text_ = CASE WHEN :FraudCategory = ''Oth'' THEN ''Other'' ELSE :FraudCategory END limit 10000;"
  }
}'::text WHERE
idashboardqueryid = 158 AND itenantid = 12;
